using System;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 Label excelConnectionSummary;
 void InstallExcelStatusBar(){
  var bar=new Panel{Name="ExcelStatusBar",Dock=DockStyle.Bottom,Height=34,Padding=new Padding(16,5,16,4),BackColor=ModernUi.Soft};
  excelStatus.Name="ExcelSyncStatus";excelStatus.AccessibleName="Excel sync status";excelStatus.Dock=DockStyle.Fill;excelStatus.AutoSize=false;excelStatus.AutoEllipsis=true;excelStatus.TextAlign=ContentAlignment.MiddleLeft;excelStatus.Padding=Padding.Empty;excelStatus.Font=ModernUi.Body;excelStatus.ForeColor=PowTheme.Muted;excelStatus.BackColor=bar.BackColor;
  excelConnectionSummary=new Label{Name="ExcelConnectionSummary",AccessibleName="Linked Excel workbook",Dock=DockStyle.Left,Width=420,AutoEllipsis=true,TextAlign=ContentAlignment.MiddleLeft,Padding=new Padding(0,0,16,0),Font=ModernUi.Body,BackColor=bar.BackColor};
  var tooltip=new ToolTip{ShowAlways=true,AutoPopDelay=30000};Action update=()=>{tooltip.SetToolTip(excelStatus,excelStatus.Text);UpdateExcelConnectionSummary();if(excelConnectionSummary!=null)tooltip.SetToolTip(excelConnectionSummary,worksExcel==null?excelConnectionSummary.Text:worksExcel.PathName);};excelStatus.TextChanged+=(s,e)=>update();update();bar.Disposed+=(s,e)=>tooltip.Dispose();
  bar.Paint+=(s,e)=>{using(var line=new Pen(PowTheme.Line))e.Graphics.DrawLine(line,0,0,bar.Width,0);};bar.Controls.Add(excelStatus);bar.Controls.Add(excelConnectionSummary);InstallLinkAnimation(bar);if(powSaveIndicator!=null){powSaveIndicator.Dock=DockStyle.Right;powSaveIndicator.AutoSize=false;powSaveIndicator.Width=320;powSaveIndicator.AutoEllipsis=true;powSaveIndicator.TextAlign=ContentAlignment.MiddleRight;powSaveIndicator.Padding=new Padding(0,0,12,0);powSaveIndicator.Font=ModernUi.Body;powSaveIndicator.ForeColor=PowTheme.Muted;powSaveIndicator.BackColor=bar.BackColor;bar.Controls.Add(powSaveIndicator);tooltip.SetToolTip(powSaveIndicator,"");powSaveIndicator.TextChanged+=(s,e)=>tooltip.SetToolTip(powSaveIndicator,string.IsNullOrEmpty(currentPowPath)?powSaveIndicator.Text:powSaveIndicator.Text+"\n"+currentPowPath);}bar.Resize+=(s,e)=>excelConnectionSummary.Width=Math.Min(520,Math.Max(240,bar.ClientSize.Width*45/100));Controls.Add(bar);/* Dock order: the bottom bar must be laid out before the Fill workspace, otherwise it covers the bottom of tables. */bar.SendToBack();
 }
 void UpdateExcelConnectionSummary(){if(excelConnectionSummary==null||excelConnectionSummary.IsDisposed)return;excelConnectionSummary.Text=worksExcel==null?"Excel: not linked":excelBroken?"Excel: reconnect required · "+System.IO.Path.GetFileName(worksExcel.PathName):"Excel linked: "+System.IO.Path.GetFileName(worksExcel.PathName);excelConnectionSummary.ForeColor=worksExcel!=null&&!excelBroken?PowTheme.Teal:PowTheme.Muted;}
}
}
